/// The glass layer. Design handoff section 6, an accepted amendment to
/// product brief 6.6.
///
/// Every raised surface is glass; the ground, the 3D canvas and INK are
/// not. Text, numbers, callouts, sliders and check marks are full
/// opacity always - glass is the surface under a value, never the value.
///
/// Compose these through GlassSurface. A widget that builds its own
/// BackdropFilter is the bug this class exists to prevent.
class BpGlass {
  BpGlass._();

  /// The fill every glass surface is built from, at its step's alpha.
  /// A function, not five constants: a theme change moves all of it.
  static Color tint(double alpha) =>
      const Color.fromARGB(255, 30, 38, 34).withValues(alpha: alpha);

  /// The 1px border on neutral glass.
  static Color hairline([double alpha = 0.12]) =>
      const Color.fromARGB(255, 220, 227, 220).withValues(alpha: alpha);

  /// The light catching the top edge of the pane.
  static Color highlight([double alpha = 0.08]) =>
      const Color.fromARGB(255, 220, 227, 220).withValues(alpha: alpha);

  static const double saturate = 150;
}

/// The five depths, shallowest first. A surface over CONTENT is denser
/// than one over the GROUND - that is what these are, not five greys.
/// Do not go below a step's alpha.
enum GlassDepth {
  /// sits over the ground: web side columns, scrollback, the photo-fit invitation
  panel(alpha: 0.35, blur: 18, radius: BpRadius.card),
  /// recessed in a panel: field wells, segmented controls, rail items
  well(alpha: 0.36, blur: 14, radius: BpRadius.control),
  /// library cards, plan cards, notes, the credits panel, the avatar
  card(alpha: 0.44, blur: 16, radius: BpRadius.card),
  /// over the viewport: the composer, viewport pills, browser chrome
  pill(alpha: 0.48, blur: 18, radius: BpRadius.control),
  /// over everything: the bottom sheet, the device bezel, the tab bar, the web status line
  float(alpha: 0.56, blur: 24, radius: BpRadius.float);

  const GlassDepth({
    required this.alpha,
    required this.blur,
    required this.radius,
  });

  final double alpha;
  final double blur;
  final double radius;
}

/// Tinted glass: same blur, keeps its hue, and the border takes the tint
/// rather than the neutral hairline - which is why the two alphas differ.
enum GlassTint {
  /// the clearance callout, the active plan card
  warn(color: Color(0xFFFFB000), alpha: 0.1, borderAlpha: 0.65),
  /// the pipeline banner, anything about a reference body
  ref(color: Color(0xFF35C6E8), alpha: 0.1, borderAlpha: 0.45),
  /// a pill or segment in its selected state
  active(color: Color(0xFFFFB000), alpha: 0.18, borderAlpha: 0.7);

  const GlassTint({
    required this.color,
    required this.alpha,
    required this.borderAlpha,
  });

  final Color color;
  final double alpha;
  final double borderAlpha;

  Color get fill => color.withValues(alpha: alpha);
  Color get border => color.withValues(alpha: borderAlpha);
}

